"use client";

import { Field as FieldPrimitive } from "@base-ui/react/field";
import { Fieldset as FieldsetPrimitive } from "@base-ui/react/fieldset";
import { cva } from "class-variance-authority";
import type { ComponentProps, CSSProperties, ReactNode } from "react";
import type { FieldKnobStyle } from "@/components/control-ui/knob-contracts/field-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { Separator } from "@/components/control-ui/ui/separator";

export type FieldProps = ComponentProps<"div"> & {
  orientation?: "vertical" | "horizontal" | "responsive";
  name?: string;
  disabled?: boolean;
  invalid?: boolean;
  validationMode?: "onSubmit" | "onBlur" | "onChange";
  validate?: FieldPrimitive.Root.Props["validate"];
  validationDebounceTime?: number;
} & { style?: CSSProperties & FieldKnobStyle };

export type FieldLabelVariant = "default" | "card";

export type FieldLabelProps = Omit<ComponentProps<"label">, "style"> & {
  variant?: FieldLabelVariant;
  style?: CSSProperties & FieldKnobStyle;
};

export type FieldContentProps = ComponentProps<"div"> & { style?: CSSProperties & FieldKnobStyle };

export type FieldTitleProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & FieldKnobStyle };

export type FieldControlProps = Omit<ComponentProps<"input">, "style"> &
  Pick<ComponentProps<typeof FieldPrimitive.Control>, "render"> & { style?: CSSProperties & FieldKnobStyle };

export type FieldDescriptionProps = Omit<ComponentProps<"p">, "style"> & { style?: CSSProperties & FieldKnobStyle };

export type FieldErrorMatch = boolean | keyof ValidityState;

export type FieldErrorProps = Omit<ComponentProps<"div">, "style"> & {
  match?: FieldErrorMatch;
  style?: CSSProperties & FieldKnobStyle;
};

export type FieldGroupVariant = "default" | "card";

export type FieldGroupProps = ComponentProps<"div"> & { variant?: FieldGroupVariant; style?: CSSProperties & FieldKnobStyle };

export type FieldSeparatorProps = Omit<ComponentProps<"div">, "style"> & {
  children?: ReactNode;
  style?: CSSProperties & FieldKnobStyle;
};

export type FieldItemProps = ComponentProps<"div"> & { disabled?: boolean; style?: CSSProperties & FieldKnobStyle };

export type FieldSetProps = Omit<ComponentProps<"fieldset">, "style"> & { style?: CSSProperties & FieldKnobStyle };

export type FieldLegendVariant = "default" | "section";

export type FieldLegendProps = Omit<ComponentProps<"div">, "style"> & {
  variant?: FieldLegendVariant;
  style?: CSSProperties & FieldKnobStyle;
};

const fieldVariants = cva("group/field flex w-full", {
  variants: {
    orientation: {
      vertical:
        "flex-col items-start [&>[data-control-ui=field][data-slot=content]]:w-full [&>[data-control-ui=field][data-slot=control]]:w-full",
      horizontal:
        "flex-row items-center [&>[data-control-ui=field][data-slot=label]]:flex-auto has-[>[data-control-ui=field][data-slot=content]]:items-start",
      responsive:
        "flex-col items-start [&>[data-control-ui=field][data-slot=content]]:w-full [&>[data-control-ui=field][data-slot=control]]:w-full @md/field-group:flex-row @md/field-group:items-center @md/field-group:[&>[data-control-ui=field][data-slot=content]]:w-auto @md/field-group:[&>[data-control-ui=field][data-slot=control]]:w-auto @md/field-group:[&>[data-control-ui=field][data-slot=label]]:flex-auto @md/field-group:has-[>[data-control-ui=field][data-slot=content]]:items-start",
    },
  },
  defaultVariants: {
    orientation: "vertical",
  },
});

export function Field({ className, orientation = "vertical", ...props }: FieldProps) {
  return (
    <FieldPrimitive.Root
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="root"
      data-orientation={orientation}
      className={cn(fieldVariants({ orientation }), className)}
      {...props}
    />
  );
}

export function FieldContent({ className, ...props }: FieldContentProps) {
  return (
    <div
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="content"
      className={cn("flex min-w-0 flex-1 flex-col", className)}
      {...props}
    />
  );
}

export function FieldTitle({ className, ...props }: FieldTitleProps) {
  return (
    <div data-control-ui="field" data-control-family="field" data-field-kind="field" data-slot="title" className={className} {...props} />
  );
}

export function FieldLabel({ className, variant = "default", ...props }: FieldLabelProps) {
  return (
    <FieldPrimitive.Label
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="label"
      data-variant={variant}
      data-focus-ring={variant === "card" ? "within" : undefined}
      className={cn(
        variant === "card" &&
          "flex w-full items-start gap-3 self-stretch [&>[data-control-family=choice]]:mt-[calc((1lh_-_var(--cui-choice-size))/2)]",
        className,
      )}
      {...props}
    />
  );
}

export function FieldControl({ className, render, ...props }: FieldControlProps) {
  const classes = cn("w-full", className);

  if (render !== undefined) {
    return (
      <FieldPrimitive.Control
        data-control-ui="field"
        data-control-family="field"
        data-field-kind="field"
        data-slot="control"
        className={classes}
        render={render}
        {...props}
      />
    );
  }

  return (
    <FieldPrimitive.Control
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="control"
      data-control="true"
      data-size="md"
      className={classes}
      {...props}
    />
  );
}

export function FieldDescription({ className, ...props }: FieldDescriptionProps) {
  return (
    <FieldPrimitive.Description
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="description"
      className={className}
      {...props}
    />
  );
}

export function FieldError({ className, ...props }: FieldErrorProps) {
  return (
    <div data-control-ui="field" data-control-family="field" data-field-kind="field" data-slot="error-reserve" className="min-h-[1lh]">
      <FieldPrimitive.Error
        data-control-ui="field"
        data-control-family="field"
        data-field-kind="field"
        data-slot="error"
        className={className}
        {...props}
      />
    </div>
  );
}

export function FieldGroup({ className, variant = "default", ...props }: FieldGroupProps) {
  return (
    <div
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="group"
      data-variant={variant}
      className={cn("group/field-group @container/field-group flex flex-col", className)}
      {...props}
    />
  );
}

export function FieldSeparator({ children, className, ...props }: FieldSeparatorProps) {
  return (
    <div
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="separator"
      data-content={children ? "true" : undefined}
      className={cn("relative", className)}
      {...props}
    >
      <Separator className={children ? "absolute top-1/2" : undefined} />
      {children ? (
        <span
          data-control-ui="field"
          data-control-family="field"
          data-field-kind="field"
          data-slot="separator-content"
          className="relative block w-fit"
        >
          {children}
        </span>
      ) : null}
    </div>
  );
}

export function FieldItem({ className, ...props }: FieldItemProps) {
  return (
    <FieldPrimitive.Item
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="item"
      className={cn("flex items-center", className)}
      {...props}
    />
  );
}

export function FieldSet({ className, ...props }: FieldSetProps) {
  return (
    <FieldsetPrimitive.Root
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="set"
      className={cn("flex flex-col", className)}
      {...props}
    />
  );
}

export function FieldLegend({ className, variant = "default", ...props }: FieldLegendProps) {
  return (
    <FieldsetPrimitive.Legend
      data-control-ui="field"
      data-control-family="field"
      data-field-kind="field"
      data-slot="legend"
      data-variant={variant}
      className={className}
      {...props}
    />
  );
}
